contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address addr) public payable {
        require(addr != address(0), "zero address");

        (bool okRate, bytes memory rateData) = address(c.savings()).staticcall(
            abi.encodeWithSignature("exchangeRate()")
        );
        uint256 exchangeRate = okRate && rateData.length >= 32
            ? abi.decode(rateData, (uint256))
            : 0;

        uint256 mAssetAmt = 1e18;
        (bool okM, bytes memory mData) = address(c.mAsset()).staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(this))
        );
        if (okM && mData.length >= 32) {
            uint256 bal = abi.decode(mData, (uint256));
            if (bal < mAssetAmt) {
                mAssetAmt = bal;
            }
        }

        bool supplied = false;
        if (mAssetAmt > 0) {
            try c.supplyTokenTo(mAssetAmt, addr) {
                supplied = true;
            } catch {
                supplied = false;
            }
        }

        uint256 stored = c.imBalances(addr);
        uint256 expected = (stored * exchangeRate) / 1e18;

        uint256 actual = c.balanceOfToken(addr);

        assert(supplied ? actual == expected : true);
    }

    receive() external payable {}
}

