            reverted = false;
            returned = v;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 creditsAfter = c.imBalances(address(this));
            uint256 creditsBurned = creditsBefore - creditsAfter;
            uint256 minBurned = (boundedRedeem * 1e18 + exchangeRate - 1) / exchangeRate;
            assert(creditsBurned >= minBurned && returned >= boundedRedeem);
        } else {
            assert(boundedRedeem > maxRedeemable);
        }
    }

    receive() external payable {}
}

