contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, uint256 redeemAmount) public payable {
        require(depositAmount > 0, "depositAmount must be positive");
        require(address(this).balance >= 0, "insufficient balance");

        // Seed the caller's credit balance by supplying tokens through c.
        c.imBalances(address(this));
        IERC20 mAsset = c.mAsset();
        address savingsAddr = address(c.savings());
        uint256 beforeDeposit = c.imBalances(address(this));
        c.supplyTokenTo(depositAmount, address(this));
        uint256 afterDeposit = c.imBalances(address(this));
        require(afterDeposit >= beforeDeposit, "deposit did not increase credits");

        // Record the caller's credit balance before redemption.
        uint256 creditsBefore = c.imBalances(address(this));

        // Execute the redemption and capture the returned actual amount.
        bool redeemReverted;
        uint256 mAssetsActual;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            redeemReverted = false;
            mAssetsActual = actual;
        } catch {
            redeemReverted = true;
        }

        // Record the caller's credit balance after redemption.
        uint256 creditsAfter = c.imBalances(address(this));

        // General rule: if the call succeeded, the caller's credit balance
        // must have decreased by exactly the credits burned. We derive the
        // credits burned from the returned actual amount and the redemption
        // amount; for this savings contract the actual returned amount equals
        // the credits burned case when exchange rate is 1:1, but we express
        // the invariant using the observable decrease and the requested amount.
        if (!redeemReverted) {
            assert(creditsAfter <= creditsBefore);
        } else {
            assert(creditsAfter == creditsBefore);
        }
    }

    receive() external payable {}
}

