        // We can read imBalances before and after.
        uint256 imBefore = c.imBalances(address(this));
        // After the call, read again.
        uint256 imAfter = c.imBalances(address(this));

        // The rule: if the call succeeded, then imAfter <= imBefore (credits burned or same).
        // Also, if the call succeeded, returned must be <= the mAsset spent? Not directly observable.
        // But we can assert that imAfter == imBefore - returned? No, returned is in mAssets, not credits.
