contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount) public payable {
        require(true);

        address underlying = c.depositToken();

        // Ensure the caller has enough mAsset to transfer to c
        (bool ok, bytes memory data) = underlying.call(
            abi.encodeWithSignature("balanceOf(address)", address(this))
        );
        require(ok && data.length >= 32, "balanceOf failed");
        uint256 callerBalBefore = abi.decode(data, (uint256));
        require(callerBalBefore >= mAssetAmount, "insufficient mAsset balance");

        // c must have received (or be pre-funded with) mAsset to redeem
        (ok, data) = underlying.call(
            abi.encodeWithSignature("balanceOf(address)", address(c))
        );
        require(ok && data.length >= 32, "balanceOf failed");
        uint256 cBalBefore = abi.decode(data, (uint256));
        require(cBalBefore >= mAssetAmount, "c has insufficient mAsset");

        bool reverted;
        try c.redeemToken(mAssetAmount) returns (uint256 actual) {
            reverted = false;
            (ok, data) = underlying.call(
                abi.encodeWithSignature("balanceOf(address)", address(this))
            );
            require(ok && data.length >= 32, "balanceOf failed");
            uint256 callerBalAfter = abi.decode(data, (uint256));

            assert(callerBalAfter - callerBalBefore == actual);
        } catch {
            reverted = true;
            assert(reverted);
        }
    }

    receive() external payable {}
}

