contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    address public owner;

    function run() public payable {
        // The owner is the address that deployed c, which is this test contract.
        bool isOwner = (address(this) == address(c) || msg.sender == address(c));
        // msg.sender in the test is the EOA; c's owner is this contract.
        // Determine whether the caller is the owner of c.
        // We cannot read _contractOwner, so we use the observable effect: only the owner's call succeeds.

        bool reverted;
        try c.approveMax() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: approveMax succeeds if and only if the caller is the owner of c.
        // Since c's owner is the deployer of c (this test contract), and the caller of run
        // may be different, the rule is: reverted == (msg.sender != address(this)).
        // But the test contract deploys c, so address(this) == owner. Thus:
        // approveMax reverts iff msg.sender != address(this).
        assert(reverted == (msg.sender != address(this)));
    }

    receive() external payable {}
}

