contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(supplyAmount > 0, "need supply");

        // Give this test contract redeemable credited balance by supplying mAsset through c.
        IERC20 mAsset = IERC20(c.depositToken());
        mAsset.transfer(address(this), 0); // no-op; only used to make type available? avoid

        // We need mAsset to call supplyTokenTo. The test contract must first hold mAsset.
        // Since we cannot mint, require a precondition that this test already has enough mAsset.
        require(mAsset.balanceOf(address(this)) >= supplyAmount, "need mAsset");

        mAsset.approve(address(c), supplyAmount);
        c.supplyTokenTo(supplyAmount, address(this));

        // Make the deciding call, capturing the return value. The call must succeed for the rule.
        // If it reverts, the assert below is skipped because we simply continue; but to keep the
        // rule general we require it not revert by catching and only asserting on success.
        uint256 mAssetBalanceBefore = mAsset.balanceOf(address(c));
        uint256 returnedActual;
        bool reverted;
        try c.redeemToken(redeemAmount) returns (uint256 actual) {
            returnedActual = actual;
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 mAssetBalanceAfter = mAsset.balanceOf(address(c));

        // General rule: if redeemToken returns successfully, the returned amount equals the
        // decrease of c's mAsset balance caused by the call. If it reverted, no balance change
        // should have occurred from the redeeming part (the function is atomic).
        if (!reverted) {
            assert(returnedActual == mAssetBalanceBefore - mAssetBalanceAfter);
        } else {
            assert(mAssetBalanceAfter == mAssetBalanceBefore);
        }
    }

    receive() external payable {}
}

