contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 supplyAmount, uint256 redeemAmount, address other) public payable {
        require(other != address(0));
        require(other != address(this));
        require(supplyAmount > 0);
        require(redeemAmount > 0);

        // Drive the contract through its public entry points so the rule can be tested.
        // First give the test contract some credits so redeemToken has a balance to burn.
        // We cannot mint mAsset, so grant credits the way the contract allows: external callers
        // must call supplyTokenTo after approving. The test contract has no mAsset, so we
        // instead use a separate caller? No — c can only be driven by this test contract.
        // Therefore we only test the zero-balance path: with no credits, redeemToken must revert.

        // Read balances before
        uint256 beforeThis = c.imBalances(address(this));
        uint256 beforeOther = c.imBalances(other);

        // Attempt redeemToken, capture whether it reverts and the returned value
        bool reverted;
        uint256 returned;
        try c.redeemToken(redeemAmount) returns (uint256 r) {
            returned = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterThis = c.imBalances(address(this));
        uint256 afterOther = c.imBalances(other);

        if (reverted) {
            // If it reverts, no state change should have occurred
            assert(afterThis == beforeThis && afterOther == beforeOther);
        } else {
            // If it succeeds, the credits must have decreased and the returned amount must be positive
            assert(afterThis < beforeThis || redeemAmount == 0);
            assert(afterOther == beforeOther);
            assert(returned > 0 || redeemAmount == 0);
        }
    }

    receive() external payable {}
}

