    function run(uint256 mAssetAmount) public payable {
        // Setup: supply mAsset to c so there is something to redeem.
        // The test contract must already hold mAsset and approve c; both are done
        // via the public surface of the mAsset token returned by c.depositToken().
        // The test contract may need to be pre-funded; but we can at least
        // attempt supplyTokenTo after approving c.
        IERC20 mAsset = IERC20(c.depositToken());

        // Approve c to pull mAsset from this contract (top-level call on mAsset, not c).
        mAsset.approve(address(c), type(uint256).max);

        // Supply mAsset to c so that redeeming has something to work with.
        // Only call if this contract has a balance to avoid guaranteed revert.
        uint256 mAssetBal = mAsset.balanceOf(address(this));
        if (mAssetBal > 0) {
            c.supplyTokenTo(mAssetBal, address(this));
        }

        // Read the mAsset balance of this contract before the deciding call.
        uint256 balanceBefore = mAsset.balanceOf(address(this));

        bool reverted;
        uint256 returned;
        try c.redeemToken(mAssetAmount) returns (uint256 r) {
            reverted = false;
            returned = r;
        } catch {
