        // Read the mAsset balance after the deciding call.
        uint256 balanceAfter = mAsset.balanceOf(address(this));

        // The returned mAssetsActual must equal the actual mAsset received by this
        // contract when the call completes. If it reverted, balanceAfter == balanceBefore.
        // To avoid underflow in the assertion, compare via addition:
        //   returned + balanceBefore == balanceAfter
